const b=$json;
const topics=String(b['Topics to cover']||b.topics||'').trim() || 'React Hooks';
const level=String(b['Study level']||b.level||'').trim() || 'Undergraduate';
let deadline=String(b['Deadline']||b.deadline||'').trim();
if(!deadline){ deadline=new Date(Date.now()+7*24*3600*1000).toISOString(); }
return [{ json:{ topics, requirement:topics, deadline, level } }];

let raw=$json.text||'{}';raw=String(raw).replace(/```json/gi,'').replace(/```/g,'').trim();
let r;try{r=JSON.parse(raw);}catch(e){r={prerequisites:[]};}
let pr=Array.isArray(r.prerequisites)?r.prerequisites:[];
while(pr.length<2)pr.push({topic:'General background',question:'Do you have the general background needed?'});
pr=pr.slice(0,2).map(p=>({topic:String(p.topic||'Prerequisite'),question:String(p.question||('Do you know '+(p.topic||'this')+'?'))}));
const k=$('Requirement Intake').first().json;
return [{ json:{ prerequisites:pr, topics:k.topics, requirement:k.requirement, deadline:k.deadline, level:k.level } }];

const pr=$('Parse Prerequisites').first().json.prerequisites||[];const form=$json;
const prereqSummary=pr.map(p=>p.topic+': '+String(form[p.question]||'No')).join('; ');
const k=$('Requirement Intake').first().json;
return [{ json:{ prereqSummary, topics:k.topics, requirement:k.requirement, deadline:k.deadline, level:k.level } }];

const pa = $('Parse Prerequisite Answers').first().json;
let raw = $json.text || '{}';
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
let r;
try { r = JSON.parse(raw); } catch (e) { r = { plausible:true, reason:'', goal:pa.requirement, thoughts:'', syllabus:[{topic:pa.requirement,detail:'',sessions:1,reason:''}] }; }
const plausible = r.plausible !== false;
const out = { plausible, reason:r.reason||'', goal:r.goal||pa.requirement, thoughts:r.thoughts||'', level:pa.level, deadline:pa.deadline };
if (!plausible) { return [{ json: out }]; }
let syl = Array.isArray(r.syllabus) && r.syllabus.length ? r.syllabus : [{topic:pa.requirement,detail:'',sessions:1,reason:''}];
let topics = syl.map(t => ({ topic:String(t.topic||'Topic'), detail:String(t.detail||''), reason:String(t.reason||''), cnt: Math.max(1, Math.min(20, Math.round(Number(t.sessions)||1))) }));
// level-based MINIMUM total sessions; pad round-robin so every topic is covered and the floor is met
const lvl = String(pa.level||'').toLowerCase();
let minSessions = 5;
if (lvl.includes('expert') || lvl.includes('professional')) minSessions = 7;
else if (lvl.includes('post')) minSessions = 6;
else if (lvl.includes('under')) minSessions = 5;
else if (lvl.includes('high') || lvl.includes('school')) minSessions = 4;
let total = topics.reduce((a,t)=>a+t.cnt,0);
let ri = 0;
while (total < minSessions) { topics[ri % topics.length].cnt += 1; total++; ri++; }
const sessions = [];
topics.forEach(t => { for (let k=1;k<=t.cnt;k++){ sessions.push({ topic:t.topic, detail:t.detail, label:(t.cnt>1?(' (session '+k+'/'+t.cnt+')'):''), reason:t.reason }); } });
// Read time window from upstream (set by Extract Decline Context on revise, defaults on first run)
let earliestHour = ($json.earliestHour !== undefined && $json.earliestHour !== null) ? $json.earliestHour : 9;
let latestHour   = ($json.latestHour   !== undefined && $json.latestHour   !== null) ? $json.latestHour   : 20;
const TARGET_TZ='Asia/Kolkata';
const kolkata = (d)=> new Date(d.toLocaleString('en-US',{timeZone:TARGET_TZ}));
const toISO = (d)=> new Date(d.getTime() - d.getTimezoneOffset()*60000).toISOString().replace('Z','+05:30');
let startDay = kolkata(new Date()); startDay.setDate(startDay.getDate()+1); startDay.setHours(0,0,0,0);
let dl = kolkata(new Date(pa.deadline)); if (isNaN(dl.getTime())) { dl = new Date(startDay.getTime() + sessions.length*86400000); } dl.setHours(0,0,0,0);
let D = Math.floor((dl.getTime() - startDay.getTime())/86400000) + 1; if (D < 1) D = 1;
const N = sessions.length;
const dayOf = sessions.map((s,i)=> N===1 ? 0 : Math.round(i*(D-1)/(N-1)));
const perDay = {}; dayOf.forEach(d=> perDay[d]=(perDay[d]||0)+1);
const seen = {};
const scheduled = sessions.map((s,i)=>{
  const d = dayOf[i];
  const idxInDay = (seen[d] = (seen[d]||0)); seen[d]++;
  const cntThisDay = perDay[d];
  const span = latestHour - earliestHour;
  const step = cntThisDay>1 ? Math.max(1, Math.floor(span/cntThisDay)) : 0;
  const hour = Math.min(latestHour - 1, earliestHour + idxInDay * step);
  const start = new Date(startDay.getTime() + d*86400000); start.setHours(hour,0,0,0);
  const end = new Date(start.getTime() + 60*60000);
  const topic = s.topic + s.label;
  const content = topic + (s.detail ? (': '+s.detail) : '');
  return { session:i+1, topic, detail:s.detail, content, reason:s.reason, slotStart:toISO(start), slotEnd:toISO(end) };
});
out.requestId = 'req_' + Date.now();
out.deadlineISO = pa.deadline;
out.parts = scheduled;
out.partCount = scheduled.length;
out.minSessions = minSessions;
out.planText = scheduled.map(s => s.slotStart.split('T')[0] + ' @ ' + s.slotStart.split('T')[1].substring(0,5) + ' - ' + s.topic + (s.reason ? (' ('+s.reason+')') : '')).join('\n');
return [{ json: out }];

