// Extract decline reason and parse any time-window constraint from it.
// This runs only on the decline branch, before AI Revise Plan.
const approval = $('Propose Plan & Wait Approval').first().json;
const declineReason = (approval.data && approval.data['Reason (if declining)']) || '';
const prev = $('Parse & Schedule').first().json;

let earliestHour = 9;
let latestHour   = 20;
const timeMatch = declineReason.match(/(\d{1,2})\s*(?:am|AM)?\s*(?:to|-)\s*(\d{1,2})\s*(am|pm|AM|PM)/i);
if (timeMatch) {
  earliestHour = parseInt(timeMatch[1]);
  let endH = parseInt(timeMatch[2]);
  if (/pm/i.test(timeMatch[3]) && endH < 12) endH += 12;
  latestHour = endH;
}

return [{ json: { ...prev, declineReason, earliestHour, latestHour } }];
